// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('Напоминания', () => {
  test('RM-03 Профиль — «תזכורות במערכת» и «הודעות במייל, SMS ו־WhatsApp», окно согласия #6a86f7fa @prod-safe @mobile', async ({ page }) => {
    // 1. Открыть `/profile` → раздел «הגדרות».
    await page.goto('/profile');
    await expect(page.getByRole('heading', { name: 'הגדרות' })).toBeVisible();
    const sw = page.getByRole('switch', { name: /^תזכורות במערכת/ });
    await expect(sw).toBeVisible();
    await expect(sw).toContainText('כולל התראות ל: זמני תפילה, תפילין, ספירת העומר, ראש חודש ומועדים');
    await expect(sw).toContainText('בדפדפן לא נשלחות התראות למכשיר');
    const consentRow = page.getByRole('button', { name: /^הודעות במייל, SMS ו־WhatsApp/ });
    await expect(consentRow).toContainText('מאושר');
    for (const old of ['תזכורות והתראות', 'הסכמה לקבלת התראות', 'הסכמה נשמרה', 'לא אושרו תזכורות']) {
      await expect(page.locator('body')).not.toContainText(old);
    }

    // 2. «הודעות במייל, SMS ו־WhatsApp»; прочитать окно; закрыть «סגירה» без сохранения.
    await consentRow.click();
    const dialog = page.getByRole('dialog');
    await expect(dialog.getByText('הודעות במייל, SMS ו־WhatsApp', { exact: true })).toBeVisible();
    const checkbox = dialog.getByRole('checkbox', { name: /אני מאשר לקבל התראות למייל/ });
    await expect(checkbox).toHaveAttribute('aria-checked', 'true');
    await expect(dialog.getByText('אפשר לשנות את הבחירה בכל עת.')).toBeVisible();
    await expect(dialog.getByText('אפשר להצטרף גם בלי לאשר')).toHaveCount(0);
    await expect(dialog.getByRole('button', { name: 'שמירה' })).toBeDisabled();
    await dialog.getByRole('button', { name: 'סגירה' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(consentRow).toContainText('מאושר');
  });
});
